(29038, 'Matthew 22:25', 'Matthew', 22, 25, 'په یو وخت کې اووه ورونه وو، لومړني ورور یې واده وکړ او هغه بې‌اولاده مړ شو او د هغه کونډه د هغه ورور ته پاتې شوه.', 'په یو وخت کې اووه ورونه وو، لومرنی ورور یې واده وکر او هغه بې‌اولاده مر شو او د هغه کونده د هغه ورور ته پاتې شوه.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Matthew_22_25.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(29039, 'Matthew 22:26', 'Matthew', 22, 26, 'په دې ډول دوهم، درېم او تر اووم وروره پورې د هغې ښځې سره ودونه وکړل او ټول بې‌اولاده مړه شول.', 'په دې دول دوهم، درېم او تر اووم وروره پورې د هغې شجې سره ودونه وکرل او تول بې‌اولاده مره شول.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Matthew_22_26.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(29040, 'Matthew 22:27', 'Matthew', 22, 27, 'په پای کې هغه ښځه هم مړه شوه.', 'په پای کې هغه شجه هم مره شوه.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Matthew_22_27.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(29041, 'Matthew 22:28', 'Matthew', 22, 28, 'نو مونږ ته ووایه چې د قیامت په ورځ به هغه د کوم یو ښځه وي؟ ځکه چې ټولو ورسره ودونه کړي وو؟»', 'نو مونز ته ووایه چې د قیامت په ورج به هغه د کوم یو شجه وی؟ جکه چې تولو ورسره ودونه کری وو؟»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Matthew_22_28.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(29042, 'Matthew 22:29', 'Matthew', 22, 29, 'عیسی ځواب ورکړ: «ستاسو غلطي په دې کې ده چې نه د خدای په کلام پوهېږئ او نه د خدای د قدرت څخه خبر یئ.', 'عیسی جواب ورکر: «ستاسو غلطی په دې کې ده چې نه د خدای په کلام پوهېزی او نه د خدای د قدرت چخه خبر یی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Matthew_22_29.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(29043, 'Matthew 22:30', 'Matthew', 22, 30, 'ځکه چې د قیامت په ورځ کله چې مړي بیا راژوندي کیږي، نه سړي ودونه کوي او نه به ښځې چاته واده کیږي، خو هغوی به د اسمان د فرښتو په شان وي.', 'جکه چې د قیامت په ورج کله چې مری بیا راژوندی کیزی، نه سری ودونه کوی او نه به شجې چاته واده کیزی، خو هغوی به د اسمان د فرشتو په شان وی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Matthew_22_30.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
